proc sql;
create table ibesforecast2 as
select a.*, b.pdi, b.dilfac, b.sdates
	from ibesforecast a left join ibes.idsum b
	on a.ticker=b.ticker & a.statpers<=a.fpedats & a.fpedats>=b.sdates
	order by a.ticker, a.fpedats, a.statpers desc, b.sdates desc;
quit;
endrsubmit;
rsubmit;
data ibesforecast3;
	set ibesforecast2;
	where sdates^=.;
	by ticker fpedats descending statpers descending sdates;
	if first.fpedats;
run;
endrsubmit;
rsubmit;
data ibesforecast4;
	set ibesforecast3;
	if pdi='P' then meanest=meanest*(1/dilfac); * [Estimate, Primary] = [Estimate, Diluted] * DILFAC ;
run;
endrsubmit;

