proc sql;
create table sample as
select distinct a.*, c.filelength, case when b.nexhibits=. then 1 else b.nexhibits end as nexhibits, 
		c.nmatches as nmatches_GAAP, c.firstsent as firstsent_GAAP, c.firstchar as firstchar_GAAP,
		d.nmatches as nmatches_NG, d.firstsent as firstsent_NG, d.firstchar as firstchar_NG
	from promin.sample a
		left join exhibit_errors b
			on a.filename = b.filename
		left join GAAP_EPS_summary c
			on a.filename = c.filename
		left join NG_EPS_summary d
			on a.filename = d.filename;
quit;

data sample;
	set sample;
	if nmatches_GAAP=. then nmatches_GAAP=0;
	if mgr_exclude=1 & nmatches_NG=. then nmatches_NG=0;

	if firstsent_NG>0 & firstsent_GAAP>0 then do;
		if firstsent_NG>firstsent_GAAP then NG_rel_prominence = 'GAAP FIRST';
		if firstsent_NG=firstsent_GAAP then NG_rel_prominence = 'SAME';
		if firstsent_NG<firstsent_GAAP then NG_rel_prominence = 'NG FIRST';
	end;

	* a version that distinguishes based on character position, when there are sentence ties;
	if firstchar_NG>0 & firstchar_GAAP>0 then do;
		if firstchar_NG>firstchar_GAAP then NG_rel_prominence2 = 'GAAP FIRST';
		if firstchar_NG=firstchar_GAAP then NG_rel_prominence2 = 'SAME';
		if firstchar_NG<firstchar_GAAP then NG_rel_prominence2 = 'NG FIRST';
	end;
	calyear = year(date);
run;

data promin.sample_promindata;
	set sample;
run;

data sample;
	set promin.sample_promindata;
	if NG_rel_prominence2='SAME' then NG_rel_prominence2=.;
	if NG_rel_prominence2='NG FIRST' then NG_FIRST2=1;
	if NG_rel_prominence2='GAAP FIRST' then NG_FIRST2=0;

